// src/validation/patterns.ts
// Allowlists: describe what IS permitted.

// Short names: letters (any language), numbers, spaces, common punctuation
export const NAME_PATTERN = /^[\p{L}\p{M}\p{N} .,'’&()\-!/%+]+$/u;

// Usernames: lowercase letters, numbers, underscore
export const USERNAME_PATTERN = /^[a-z0-9_]{3,20}$/;

// IDs used in database paths: no slashes, spaces or quotes
export const ID_PATTERN = /^[a-z0-9_-]{1,100}$/;

// Calendar dates as "YYYY-MM-DD" (ASCII digits only)
export const DATE_KEY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

// Firebase Auth user IDs: generated by Firebase (28 mixed-case letters and digits).
// Not user text, but still used in document paths, so checked like other IDs.
export const UID_PATTERN = /^[A-Za-z0-9]{1,128}$/;

// Email addresses after lowercasing (the HTML spec's email pattern; the domain needs a dot)
export const EMAIL_PATTERN =
  /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/;

// Keys that expo-secure-store accepts
export const SECURE_KEY_PATTERN = /^[A-Za-z0-9._-]{1,200}$/;